1087	
1088	
1089	
1090	After LR symmetry breaking, the $W_{R}^{3}$ and $X_{(B-L)}$ gauge states mix and
1091	give rise to the massive $Z_{R}$ and massless (hypercharge) $B$ bosons.
1092	
1093	Subsequently, all fermions with $(B-L)$ charges, including $\nu_L$ and $N_R$, couple to $\ZR$.
1094	
1095	For chiral fermion $f$, we parametrize the $\ZR$ neutral currents by
1096	\begin{eqnarray}
1097	 \mathcal{L}_{\ZR-f-f} &=& \frac{-\kappa_{R}^f g}{\sqrt{1 - \left(1/\kappa_{R}^f\right)^2\tWSq}}\sum_{f=u,e,\dots}
1098	 \overline{f} Z_{R \mu} \gamma^\mu \left(g_{L}^{\ZR,f}P_L + g_{R}^{\ZR,f}P_R\right)f.
1099	\label{neucurrent}
1100	\end{eqnarray}
1101	$\kappa_{R}^{f}$ are the same $\kappa_{R}^{q,\ell}$ as for $\WR$.
1102	In terms of electric and isospin charges, the chiral coefficients are
1103	\begin{eqnarray}
1104	 g_{L}^{\ZR,f} &=& \left(T_{L}^{3,f} - Q^f\right)\frac{1}{\kappa_{R}^{f~2}}\tWSq,
1105	 \\
1106	 g_{R}^{\ZR,f} &=& T_{R}^{3,f} - \frac{1}{\kappa_{R}^{f~2}}\tWSq Q^f.
1107	\end{eqnarray}
1108	SU$(2)_L$, SU$(2)_R$, and U$(1)_{\rm EM}$ quantum number assignments for $f$ are summarize in Tbl.~\ref{tb:qNumbers}.
1109	
1110	For generic $\kappa_R^{q,\ell}$ normalizations, the LO $\WR,\ZR$ partial decay widths are then
1111	\begin{eqnarray}
1112	 \Gam{\WR \rightarrow q\overline{q'}} 	&=& N_c \vert V^{\rm{CKM'}}_{qq'}\vert^2 \frac{\kappa_{R}^{q 2} g^2 \MWR}{48 \pi}
1113	 \\
1114	 \Gam{\WR \rightarrow tb} 	&=& N_c \vert V^{\rm{CKM'}}_{tb}\vert^2 \frac{\kappa_{R}^{q 2} g^2 \MWR}{48 \pi}
1115						    \left(1-r_t^{\WR}\right)^2\left(1+\frac{1}{2}r_t^{\WR}\right),
1116	 \\
1117	 \Gam{\WR \rightarrow \ell N_{m'}} 	&=&     \vert Y_{\ell N_{m'}}\vert^2 \frac{\kappa_{R}^{\ell 2} g^2 \MWR}{48 \pi}
1118						\left(1-r_N^{\WR}\right)^2\left(1+\frac{1}{2}r_N^{\WR}\right),
1119	\\
1120	 \Gam{\ZR\rightarrow f\overline{f}} &=&   
1121	 N_c^f 
1122	 \cfrac{\kappa_{\ZR}^{f 2} g^2 \MZR \sqrt{1-4r_f^{\ZR}}}{48\pi\left[1 - (1/\kappa_{R}^f)^2\tWSq\right]}
1123	 \nonumber\\
1124	 &\times&
1125	 \left[(g_{L}^{\ZR,f}+g_{R}^{\ZR,f})^2(1+2r_f^{\ZR})+(g_{L}^{\ZR,f}-g_{R}^{\ZR,f})^2(1-4r_f^{\ZR})\right]
1126	 \\
1127	 r_i^{V_R} &=& \frac{m_{i}^2}{M_{V_R}^2}.
1128	\end{eqnarray}
1129	Assuming diagonal quark mixing and lepton mixing in Eq.~(\ref{eq:lrsmNuMixing}), the total $\WR,\ZR$ widths are then
1130	\begin{eqnarray}
1131	 \Gamma_{\WR} &=& 2\Gam{\WR \rightarrow q\overline{q'}} + \Gam{\WR \rightarrow tb} 
1132	 + \Gam{\WR \rightarrow e N_{1}} + \Gam{\WR \rightarrow \mu N_{2}} + \Gam{\WR \rightarrow \tau N_{3}}
1133	 \\
1134	 \Gamma_{\ZR} &=& \sum_{f} \Gam{\ZR\rightarrow f\overline{f}}
1135	\end{eqnarray}
