1149	 \hline 
1150	\end{tabular}
1151	\caption{Masses and total widths of $\WR,~\ZR$ and $N_1$ for representative parameters in Eq.(\ref{eq:lrsmInputs}).}
1152	\label{tb:lrsmParam}
1153	\end{center}
1154	\end{table}
1155	
1156	While we take $\MWR$ and $\MZR$ as independent phenomenological parameters, they are related in the LRSM by the relation
1157	\begin{equation}
1158	 \MZR = \sqrt{2\cos^2\theta_W / \cos2\theta_W} \times \MWR \approx (1.7)\times\MWR
1159	 \label{eq:massRelationship}
1160	\end{equation}
1161	As the size of $m_{N_{m'}}$ are governed by Yukawa couplings, the masses of $N_{m'}$ are largely independent of $\MWR$.
1162	For the following representative input, 
1163	\begin{equation}
1164	 \MWR=3\TeV,	\quad m_{N_1}=m_t=173.3\GeV,	\quad\text{and}\quad  m_{N_2},m_{N_3} = 10^{12}\GeV,
1165	 \label{eq:lrsmInputs}
1166	\end{equation}
1167	which we will motivate in the next section, the corresponding partial and total widths for $\WR,\ZR,$ and $N_1$ are summarized in Tb.~\ref{tb:lrsmParam}.
1168	We have checked our model against these analytic results.
1169	
1170	
1171	
